var t=`0260-aljotta`;var n=`world-0260`;var a=`MT`;var o=`southern-europe`;var s=4;var l=45;var r={en:`Aljotta`,ua:`Альйотта`};var m={en:`A traditional Malta dish made with yellow onion, garlic, tomato, bay leaf. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Мальта. Основні інгредієнти: жовта цибуля, часник, помідор, лавровий лист. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,160,`g`],[`garlic`,5,`clove`],[`extra-virgin-olive-oil`,45,`ml`],[`tomato`,190,`g`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 23 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 23 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:23,i:[[`fish-stock`,1300,`ml`],[`dry-white-wine`,120,`ml`],[`bay-leaf`,2,`leaf`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 11 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 11 хвилин до готовності й м’якості.`,t:[`poaching`],m:11,i:[[`cod`,520,`g`],[`shrimp`,220,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`lemon-juice`,35,`ml`],[`parsley`,20,`g`]]}];var d={slug:t,id:n,country:`MT`,region:o,servings:4,minutes:45,title:r,text:m,steps:g};export{a as country,d as default,n as id,l as minutes,o as region,s as servings,t as slug,g as steps,m as text,r as title};